/**
 * PGCB monthly archive access.
 *
 * The archive used to be a static JSON import, which meant every visitor
 * downloaded and parsed 13 years of records inside the JS bundle even if they
 * never opened Macro Trends. It is now served as static files under
 * `public/data/pgcb-monthly/` (generated by scripts/build_pgcb_monthly_public.py)
 * and fetched on demand:
 *
 *   _series.json   every month, chart/KPI/picker fields only — one fetch
 *   {YYYY-MM}.json one month, complete — fetched only for the month being viewed
 *
 * Per-month detail belongs in the second shape so it never re-enters the bundle.
 */

import { fetchDataJson } from '@/lib/data/runtime-data.client';

/**
 * Paths are relative to `public/data`: reads go through `fetchDataJson`, which
 * consults the publish manifest and reads the database copy when one is
 * authoritative. A month corrected after the last deploy used to be invisible
 * here — the stale static file answered 200, so nothing ever looked further.
 */
const BASE = 'pgcb-monthly';

export interface PgcbMonthlyFuelMix {
  gas: number;
  coal: number;
  hfo: number;
  diesel: number;
  hydro: number;
  solar: number;
  wind: number;
  import: number;
}

/** The fields the trend charts, KPI tiles, fuel mix and period pickers read. */
export interface PgcbMonthlySeriesRecord {
  /** The PGCB monthly report this record was read from, named as held. */
  filename?: string;
  date_key: string;
  month: string;
  year: number;
  max_evening_peak_gen: number;
  max_evening_peak_demand: number;
  total_net_generation: number;
  generation_by_fuel: PgcbMonthlyFuelMix;
}

/** A QF-MIS-03 line: this month's figure with the comparisons the sheet prints beside it. */
export interface PgcbSystemStat {
  value: number;
  when: string | null;
  prev_month: number | null;
  last_year: number | null;
  /** Set when the printed date falls outside the report month — see data_quality. */
  suspect_date?: boolean;
}

export interface PgcbCircleSplit {
  tripping: number | null;
  emergency: number | null;
  scheduled: number | null;
  total: number | null;
}

export interface PgcbCircleRow {
  circle: string;
  current: PgcbCircleSplit;
  previous: PgcbCircleSplit;
}

export interface PgcbDailyShedRow {
  date: string;
  generation_mw: number | null;
  demand_mw: number | null;
  load_shed_mw: number | null;
  time: string | null;
  zones: Record<string, number | null>;
}

export interface PgcbSubstationLoad {
  substation: string;
  /** Null when the report lists the substation but records no load for it. */
  load_mw: number | null;
  when: string | null;
}

export interface PgcbSubstationVoltage {
  substation: string;
  class: string | null;
  rated_kv: number | null;
  max_kv: number | null;
  max_when: string | null;
  min_kv: number | null;
  min_when: string | null;
}

export interface PgcbTransformerLoad {
  substation: string;
  transformer: string | null;
  voltage_level: string | null;
  capacity_mva: number | null;
  date: string | null;
  hour: string | null;
  mw: number | null;
  mvar: number | null;
  loading_pct: number;
}

export interface PgcbInterruption {
  substation: string;
  interruptions: number;
  duration: string | null;
  unserved_mwh: number | null;
}

export interface PgcbAreaLoad {
  area: string;
  key: string;
  load_mw: number;
  date?: string | null;
  hour?: string | null;
}

export interface PgcbFgmoPlant {
  plant: string;
  owner: string | null;
  fuel: string | null;
  capacity_mw: number | null;
  days_active: number;
  /** 31 chars, '1' = on FGMO that day. Packed to keep the per-month file small. */
  days: string;
}

export interface PgcbOutageEvent {
  kind: string;
  circle: string | null;
  substation: string;
  equipment: string | null;
  start: string;
  finish: string | null;
  duration: string | null;
  type: string | null;
  cause: string | null;
  unserved_load_mw: number | null;
  unserved_energy_mwh: number | null;
}

/** Everything beyond the headline figures, extracted from the source workbook. */
export interface PgcbMonthlyDetail {
  date_key: string;
  month: string;
  year: number;
  source_workbook?: string;
  sheets_present?: string[];
  system?: {
    items: Array<{
      sl: string;
      item: string;
      value: number;
      when: string | null;
      prev_month: number | null;
      last_year: number | null;
      max_till_date: number | null;
    }>;
    keyed: Record<string, PgcbSystemStat>;
  };
  area_supply_at_system_peak?: {
    areas: PgcbAreaLoad[];
    zone_totals: Record<string, number>;
    peak_context: { generation_mw?: number | null; when?: string | null };
  };
  tripping_outage?: { circles: PgcbCircleRow[]; total: PgcbCircleRow | Record<string, never> };
  unserved_energy?: { circles: PgcbCircleRow[]; total: PgcbCircleRow | Record<string, never> };
  interruptions?: PgcbInterruption[];
  substation_max_load?: PgcbSubstationLoad[];
  area_max_load?: PgcbAreaLoad[];
  substation_voltage?: PgcbSubstationVoltage[];
  transformer_loading?: PgcbTransformerLoad[];
  daily_load_shedding?: { evening_peak: PgcbDailyShedRow[]; day_peak: PgcbDailyShedRow[] };
  generation_system?: Array<{
    item: string;
    unit: string | null;
    value: number;
    date: string | null;
    time: string | null;
  }>;
  fgmo?: PgcbFgmoPlant[];
  /**
   * Figures PGCB printed in the "Current Month" column carrying a date from a
   * previous month — the earlier month's number left in the cell. Reported
   * rather than silently corrected or silently passed on.
   */
  data_quality?: {
    stale_current_month_figures: Array<{
      key: string;
      value: number;
      printed_date: string | null;
    }>;
  };
  /** Events ship separately; this is how many the events file holds. */
  outage_event_count?: number;
}

/** One month in full, including detail kept out of the series. */
export interface PgcbMonthlyRecord extends PgcbMonthlySeriesRecord {
  filename: string;
  regional_supply: Record<string, number>;
  detail?: PgcbMonthlyDetail;
}

let seriesCache: PgcbMonthlySeriesRecord[] | null = null;
let seriesInFlight: Promise<PgcbMonthlySeriesRecord[]> | null = null;

const recordCache = new Map<string, PgcbMonthlyRecord>();
const recordInFlight = new Map<string, Promise<PgcbMonthlyRecord | null>>();

/** Cached series if it has already loaded, else null. Lets callers render without a flash. */
export function peekPgcbMonthlySeries(): PgcbMonthlySeriesRecord[] | null {
  return seriesCache;
}

export function peekPgcbMonthlyRecord(dateKey: string): PgcbMonthlyRecord | null {
  return recordCache.get(dateKey) ?? null;
}

export function fetchPgcbMonthlySeries(): Promise<PgcbMonthlySeriesRecord[]> {
  if (seriesCache) return Promise.resolve(seriesCache);
  if (!seriesInFlight) {
    seriesInFlight = fetchDataJson<PgcbMonthlySeriesRecord[]>(`${BASE}/_series.json`)
      .then((res) => {
        // A tier denial still reads as a failure here, exactly as the 403 did.
        if (!res.ok) throw new Error(`pgcb monthly series: ${res.error}`);
        seriesCache = res.data;
        return res.data;
      })
      .finally(() => {
        // Cleared either way, so a failed load is retried rather than cached.
        seriesInFlight = null;
      });
  }
  return seriesInFlight;
}

export function fetchPgcbMonthlyRecord(dateKey: string): Promise<PgcbMonthlyRecord | null> {
  if (!dateKey) return Promise.resolve(null);
  const cached = recordCache.get(dateKey);
  if (cached) return Promise.resolve(cached);

  const existing = recordInFlight.get(dateKey);
  if (existing) return existing;

  const pending = fetchDataJson<PgcbMonthlyRecord>(`${BASE}/${dateKey}.json`)
    .then((res) => {
      if (!res.ok) return null;
      recordCache.set(dateKey, res.data);
      return res.data;
    })
    .catch(() => null)
    .finally(() => {
      recordInFlight.delete(dateKey);
    });

  recordInFlight.set(dateKey, pending);
  return pending;
}

const eventsCache = new Map<string, PgcbOutageEvent[]>();
const eventsInFlight = new Map<string, Promise<PgcbOutageEvent[]>>();

export function peekPgcbMonthlyEvents(dateKey: string): PgcbOutageEvent[] | null {
  return eventsCache.get(dateKey) ?? null;
}

/**
 * The month's outage event log. Larger than the rest of the month combined, so
 * it is only fetched once the reader actually opens the events table.
 */
export function fetchPgcbMonthlyEvents(dateKey: string): Promise<PgcbOutageEvent[]> {
  if (!dateKey) return Promise.resolve([]);
  const cached = eventsCache.get(dateKey);
  if (cached) return Promise.resolve(cached);

  const existing = eventsInFlight.get(dateKey);
  if (existing) return existing;

  const pending = fetchDataJson<PgcbOutageEvent[]>(`${BASE}/${dateKey}-events.json`)
    .then((res) => {
      if (!res.ok) return [] as PgcbOutageEvent[];
      eventsCache.set(dateKey, res.data);
      return res.data;
    })
    .catch(() => [] as PgcbOutageEvent[])
    .finally(() => {
      eventsInFlight.delete(dateKey);
    });

  eventsInFlight.set(dateKey, pending);
  return pending;
}

export function getLatestMonthlyDateKey(
  series: readonly PgcbMonthlySeriesRecord[] | null | undefined,
): string | null {
  if (!series || series.length === 0) return null;
  return series[series.length - 1].date_key;
}
